import React from 'react';
import { 
  X, 
  Home, 
  TrendingUp, 
  Search, 
  Settings, 
  Brain, 
  Cpu, 
  Lightbulb, 
  Wrench,
  Newspaper,
  Target
} from 'lucide-react';

const Sidebar = ({ isOpen, onClose, selectedCategory, setSelectedCategory }) => {
  const navigationItems = [
    { name: '首页', href: '/', icon: Home },
    { name: '数据分析', href: '/analytics', icon: TrendingUp },
    { name: '搜索', href: '/search', icon: Search },
    { name: '设置', href: '/settings', icon: Settings },
  ];

  const categories = [
    { name: '全部', icon: Newspaper },
    { name: 'AI新闻', icon: Brain },
    { name: 'AI框架', icon: Cpu },
    { name: '新算法', icon: Target },
    { name: '新思路', icon: Lightbulb },
    { name: '新工具', icon: Wrench },
  ];

  return (
    <>
      {/* 侧边栏 */}
      <div className={`fixed left-0 top-16 h-full w-64 bg-white border-r border-gray-200 transform transition-transform duration-300 z-20 ${
        isOpen ? 'translate-x-0' : '-translate-x-full'
      }`}>
        <div className="flex flex-col h-full">
          {/* 关闭按钮 */}
          <div className="flex justify-end p-4 lg:hidden">
            <button
              onClick={onClose}
              className="p-2 rounded-lg hover:bg-gray-100"
              aria-label="关闭菜单"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* 导航菜单 */}
          <nav className="px-4 pb-4">
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
              导航
            </h3>
            <ul className="space-y-1">
              {navigationItems.map((item) => (
                <li key={item.name}>
                  <a
                    href={item.href}
                    className="flex items-center px-3 py-2 text-sm font-medium rounded-lg text-gray-700 hover:bg-gray-100 transition-colors"
                    onClick={() => window.innerWidth < 1024 && onClose()}
                  >
                    <item.icon className="w-5 h-5 mr-3" />
                    {item.name}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          {/* 分类菜单 */}
          <div className="px-4 pb-4">
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
              资讯分类
            </h3>
            <ul className="space-y-1">
              {categories.map((category) => (
                <li key={category.name}>
                  <button
                    onClick={() => {
                      setSelectedCategory(category.name);
                      window.innerWidth < 1024 && onClose();
                    }}
                    className={`w-full flex items-center px-3 py-2 text-sm font-medium rounded-lg transition-colors ${
                      selectedCategory === category.name
                        ? 'bg-blue-100 text-blue-700'
                        : 'text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    <category.icon className="w-5 h-5 mr-3" />
                    {category.name}
                  </button>
                </li>
              ))}
            </ul>
          </div>

          {/* 底部信息 */}
          <div className="mt-auto p-4 border-t border-gray-200">
            <div className="text-xs text-gray-500">
              <p>🕒 每日8:00自动更新</p>
              <p>📊 实时数据分析</p>
              <p>🔍 智能内容推荐</p>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default Sidebar;
